<p class="eyebrow">User account</p><h1><?= e($user['first_name'].' '.$user['last_name']) ?></h1><div class="grid two dashboard-split"><section class="card"><h2>Account details</h2><dl class="detail-list"><dt>Reference</dt><dd><?= e($user['uuid']) ?></dd><dt>Email</dt><dd><?= e($user['email']) ?> · <?= !empty($user['email_verified_at'])?'verified':'unverified' ?></dd><dt>Registered</dt><dd><?= e($user['created_at']) ?></dd><dt>Last login</dt><dd><?= e($user['last_login_at']??'Never') ?></dd><dt>2FA</dt><dd><?= !empty($user['two_factor_enabled_at'])?'Enabled':'Not enabled' ?></dd></dl></section><section class="card"><h2>Change investment region</h2><p class="muted">This changes the account’s assigned market and overrides future GeoIP resolution.</p><form method="post" action="<?= e(route('admin.users.country',['user'=>$user['id']])) ?>" class="form-stack" data-confirm="Confirm the investment region change?"><?= app('csrf')->input() ?><label class="field">market<select name="country_id"><?php foreach($countries as $country): ?><option value="<?= e($country['id']) ?>"<?= (int)($user['assigned_country_id']??$user['country_id'])===(int)$country['id']?' selected':'' ?>><?= e($country['name']) ?> · <?= e($country['currency_code']) ?></option><?php endforeach; ?></select></label><label class="field">Reason <span class="muted">(optional)</span><textarea name="reason" rows="2"></textarea></label><button class="button" type="submit">Confirm market</button></form></section></div><section class="card"><h2>Account status</h2><form method="post" action="<?= e(route('admin.users.status',['user'=>$user['id']])) ?>" class="form-stack" data-confirm="Confirm this account status change?"><?= app('csrf')->input() ?><label class="field">Status<select name="account_status"><option value="active"<?= $user['account_status']==='active'?' selected':'' ?>>Active</option><option value="restricted"<?= $user['account_status']==='restricted'?' selected':'' ?>>Restricted</option><option value="suspended"<?= $user['account_status']==='suspended'?' selected':'' ?>>Suspended</option></select></label><label class="field">Reason <textarea name="reason" rows="2"><?= e($user['account_restriction_reason']??'') ?></textarea></label><button class="button button-danger" type="submit">Update status</button></form></section><section class="card"><p class="section-label">Popup message</p><h2>Send notification</h2><p class="muted">This appears as a one-time popup the next time the user loads a page.</p><form method="post" action="<?= e(route('admin.users.popup',['user'=>$user['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><label class="field">Title<input name="title" maxlength="190" required placeholder="Account update"></label><label class="field">Message<textarea name="body" rows="4" required></textarea></label><label class="field">Show this popup how many times?<input type="number" name="repeat_count" min="1" max="100" value="1" required><small>It will appear once per page load or refresh until this number is reached.</small></label><button class="button">Send popup</button></form></section><section class="card"><p class="section-label">Direct email</p><h2>Email this user</h2><p class="muted">Send a message to <?= e($user['email']) ?> using the website mail configuration.</p><form method="post" action="<?= e(route('admin.users.email',['user'=>$user['id']])) ?>" class="form-stack"><?= app('csrf')->input() ?><label class="field">Subject<input name="subject" maxlength="190" required placeholder="Message from ApexTrades"></label><label class="field">Message<textarea name="body" rows="7" maxlength="10000" required placeholder="Write your message to this user."></textarea></label><button class="button" type="submit">Send email</button></form></section><section class="card"><h2>Recent security events</h2><div class="table-wrap"><table><thead><tr><th>Event</th><th>IP</th><th>Time</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= e($event['event_type']) ?></td><td><?= e($event['ip_address']??'') ?></td><td><?= e($event['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
